(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[185],{1524:function(t,n,e){"use strict";e.r(n),n.default={code:"M2-06",title:"模擬與狀態挑戰C：競賽綜合系列",tier:"t2",unlockCode:"M2-06-SimContest",tasks:[{id:"W4-04",code:"M2-06-W4-04",title:"神箭手",description:"輸入風速與離箭靶的距離，計算弓箭手應瞄準的位置。箭靶靶心位於直角座標 (0,0) 公分。\n【重力影響（往下掉）】\n每離箭靶 8 公尺，箭就會比原本瞄準點往下掉落 1 公分（未滿 8 公尺不計）。\n【風力影響（水平偏移）】\n風速以正負數表示：正數代表往右吹、負數代表往左吹。\n每離箭靶 10 公尺，箭會受到一次風力偏移，其偏移量即為「風速的數字」（往風吹的方向偏移，未滿 10 公尺不計）。\n例如：風速為 3 → 每 10 公尺箭向右偏 3 公分；風速為 -2 → 每 10 公尺箭向左偏 2 公分。\n【任務】\n請撰寫程式，根據風速與距離計算出弓箭手應瞄準的座標位置 (x,y)，以公分為單位，使箭最終能擊中靶心 (0,0)。",examples:[{input:"3\n24",output:"-6 3",explanation:"風速 3（往右吹），距離 24 公尺：\n每 10 公尺右偏 3 公分，共 2 次 → 瞄準點水平座標為 -6。\n每 8 公尺掉 1 公分，共 3 次 → 瞄準點垂直座標為 3。\n瞄準點 (-6, 3)。"},{input:"5\n40",output:"-20 5",explanation:"風速 5（往右吹），距離 40 公尺：\n每 10 公尺右偏 5 公分，共 4 次 → 瞄準點水平座標為 -20。\n每 8 公尺掉 1 公分，共 5 次 → 瞄準點垂直座標為 5。\n瞄準點 (-20, 5)。"}],testCases:[{input:"0\n7",expectedOutput:"0 0",score:10},{input:"3\n9",expectedOutput:"0 1",score:15},{input:"-2\n24",expectedOutput:"4 3",score:20},{input:"5\n40",expectedOutput:"-20 5",score:25},{input:"-7\n105",expectedOutput:"70 13",score:30}],difficulty:"L1",difficultyLabel:"L1｜基礎",sb3Path:"m0/M2-06-SimContest/W4-04.sb3"},{id:"TYTN-01",code:"M2-06-TYTN-01",title:"遊樂場",description:"三六九主題遊樂園的門票分為兒童票與成人票兩種：\n兒童票：每張 400 元\n成人票：每張 500 元\n親子套票組：包含 1 張兒童票 + 1 張成人票，每組 800 元\n請設計一個程式，輸入兒童人數、成人人數，計算最優惠的總票價。可先盡量購買親子套票組，再補足剩餘的兒童或成人個別票",examples:[{input:"5\n5",output:"4000",explanation:"可購買 5 組親子套票組：5×800=4000\n總價 4000 元。"},{input:"6\n3",output:"3600",explanation:"可購買 3 組親子套票組：3×800=2400\n剩下 3 位兒童：3×400=1200\n總價 3600 元。"}],testCases:[{input:"5\n5",expectedOutput:"4000",score:10},{input:"6\n3",expectedOutput:"3600",score:10},{input:"4\n1",expectedOutput:"2000",score:10},{input:"2\n5",expectedOutput:"3100",score:10},{input:"7\n7",expectedOutput:"5600",score:10}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/M2-06-SimContest/TYTN-01.sb3"},{id:"cyjunior-005",code:"M2-06-cyjunior-005",title:"變速傳球的特訓",description:"康輔社為了訓練社員的反應速度，社長發明了一種忽快忽慢的「變速傳球」遊戲。N 位社員圍成一圈，編號依序為 1 到 N。遊戲從 1 號社員開始持球。遊戲總共進行 K 回合，每一回合的傳球距離取決於「目前持球者的編號」：如果目前持球者的編號是奇數：他必須向順時針方向傳 1 個人（傳給下一位）。如果目前持球者的編號是偶數：他必須向順時針方向傳 2 個人（跳過一位傳給下下位）。請注意，如果傳球後的位置超過了 N，就會回到 1 號繼續數（例如：在 5 人小組中，5 號傳 1 人會變成 1 號）。請你計算在經過 K回合的傳球後，最後球會落在幾號社員的手上？",examples:[{input:"5\n3",output:"1",explanation:"初始：在 1 號。\n第1回：1號是奇數，傳1人-> 到 2 號。\n第2回：2號是偶數，傳2人-> 到 4 號。\n第3回：4號是偶數，傳2人-> 到 6 號(超過5回到1)。\n結果：最後在 1 號。"},{input:"6\n2",output:"4",explanation:"初始：在 1 號。\n第1回：1號是奇數，傳1人-> 到 2 號。\n第2回：2號是偶數，傳2人 -> 到 4 號。結果：最後在 4 號。"}],testCases:[{input:"3\n1",expectedOutput:"2",score:10},{input:"5\n5",expectedOutput:"4",score:15},{input:"10\n4",expectedOutput:"8",score:20},{input:"8\n10",expectedOutput:"4",score:25},{input:"100\n50",expectedOutput:"100",score:30}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M2-06-SimContest/cyjunior-005.sb3"},{id:"TYTN-02",code:"M2-06-TYTN-02",title:"歌唱比賽",description:"金嗓歌唱比賽邀請 5 位評審給予選手分數，評分範圍為 0～10 分。\n請設計一個程式，讀入 5 位評審的分數後，進行以下運算：\n1. 將分數排序\n2. 去除「一個最高分」與「一個最低分」\n3. 計算剩餘 3 個分數的平均值",examples:[{input:"5\n10 8 9 9 9",output:"9",explanation:"排序後分數：10, 9, 9, 9, 8\n去除最高 10 與最低 8\n剩餘分數為 9, 9, 9 → 平均為 9"},{input:"5\n10 9 9 6 6",output:"8",explanation:"排序後分數：10, 9, 9, 6, 6\n去除最高 10 與最低 6\n剩餘分數為 6, 9, 9 → 平均 8"},{input:"5\n7 7 7 7 7",output:"7",explanation:"全部分數皆相同，排序不影響結果\n去除最高 7 與最低 7\n剩餘 7, 7, 7 → 平均 7"}],testCases:[{input:"5\n10 8 9 9 9",expectedOutput:"9",score:10},{input:"5\n10 9 9 6 6",expectedOutput:"8",score:10},{input:"5\n7 7 7 7 7",expectedOutput:"7",score:10},{input:"5\n0 10 5 5 10",expectedOutput:"7",score:10},{input:"5\n3 4 8 8 9",expectedOutput:"7",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M2-06-SimContest/TYTN-02.sb3"},{id:"TYTN-04",code:"M2-06-TYTN-04",title:"傳球遊戲",description:"學校運動會舉辦了一個趣味傳球比賽，所有參賽同學圍成一個圓圈，互相傳球。\n每個同學有一個編號（從 1 到 N）。\n遊戲規則如下：\t比賽開始時，球在 1 號同學手上。\n傳球方式：每次傳球都固定「隔 K 個人」，把球傳給下一位同學。\n例如：K=1 代表傳給下一個人，K=2 代表跳過 1 人後傳給下一個人。\n傳球會一直持續，直到球再次回到 1 號同學手上，比賽才結束。\n請你模擬這個傳球遊戲，輸出整個過程中，球依序落在誰的手上（包含最初的 1 號）。\n輸入格式：2行，每行1個整數： N：同學人數（2 > N <t 1000） K：每次傳球要隔的人數（1 < K < 1000） 輸出格式：1行，輸出一串整數，用空格間隔開。 輸出結果代表傳球過程中球依序落在誰的手上。\n第一個數字必定是 1（表示起始位置），最後一個數字也會是 1（回到起點）。",examples:[{input:"5\n2",output:"1 3 5 2 4 1",explanation:"第一行輸入5，共有 5 個人，起始在 1。\n第二行輸入2，傳球每隔 2 人 → 傳到第 3 人。\n傳球過程：1 → 3 → 5 → 2 → 4 → 1\n程式輸出包含起點 → 1 3 5 2 4 1。"},{input:"6\n3",output:"1 4 1",explanation:"第一行輸入6，共有 6 個人，起始在 1。\n第二行輸入3，傳球每隔 3 人 → 傳到第 4 人。\n傳球過程：1 → 4 → 1\n程式輸出包含起點 → 1 4 1。"},{input:"4\n1",output:"1 2 3 4 1",explanation:"第一行輸入4，共有 4 個人，起始在 1。\n第二行輸入1，傳球每隔 1 人 → 傳到第 2 人。\n傳球過程：1 → 2 →3 → 4 → 1\n程式輸出包含起點 → 1 2 3 4 1。"},{input:"12\n9",output:"1 10 7 4 1",explanation:"第一行輸入12，共有 12 個人，起始在 1。\n第二行輸入9，傳球每隔 9 人 → 傳到第 10 人。\n傳球過程：1 → 10 → 7 → 4 → 1\n程式輸出包含起點 → 1 10 7 4 1。"}],testCases:[{input:"5\n2",expectedOutput:"1 3 5 2 4 1",score:10},{input:"4\n1",expectedOutput:"1 2 3 4 1",score:10},{input:"6\n3",expectedOutput:"1 4 1",score:10},{input:"12\n9",expectedOutput:"1 10 7 4 1",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M2-06-SimContest/TYTN-04.sb3"},{id:"W4-02",code:"M2-06-W4-02",title:"歡樂抽獎",description:"每位同學會先抽出 1 顆紅球，紅球上寫有一個整數數字（0~9）。\n接著，同學可以從抽獎箱中抽出 3 顆白球，每顆白球上也各有一個整數數字（0~9）。\n同學「一定要使用紅球」，並可選擇使用 0~3 顆白球（每顆白球最多使用一次），將所選球上的數字相加。\n只要總和為 7 的倍數即可中獎。中獎等級依照「使用的白球數量」判定：\n• 不使用白球且紅球本身即為 7 的倍數：特獎\n• 使用 1 顆白球：頭獎\n• 使用 2 顆白球：二獎\n• 使用 3 顆白球：三獎\n• 若無法組成 7 的倍數：未中獎\n請撰寫程式，判斷同學最終可獲得的獎項等級（以使用白球數量最少為優先）。",examples:[{input:"2\n6 4 2",output:"三獎",explanation:"三顆白球都使用：2+6+4+2=14，是 7 的倍數。\n但任意使用 0~2 顆白球都無法湊成 7 的倍數，因此為三獎。"},{input:"8\n3 2 5",output:"未中獎",explanation:"無論怎麼選 0~3 顆白球搭配紅球，都無法使總和成為 7 的倍數。"}],testCases:[{input:"7\n1 2 3",expectedOutput:"特獎",score:10},{input:"1\n6 0 2",expectedOutput:"頭獎",score:15},{input:"2\n2 3 4",expectedOutput:"二獎",score:20},{input:"2\n6 4 2",expectedOutput:"三獎",score:25},{input:"8\n3 2 5",expectedOutput:"未中獎",score:30}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M2-06-SimContest/W4-02.sb3"},{id:"WP-04",code:"M2-06-WP-04",title:"大富翁",description:"有一條環形棋盤，共有 N 格，每一格上都標示著金錢變化，可能是「獲得金錢」（正值）、「失去金錢」（負值）或「沒有變化」（0）。\n玩家一開始站在第 1 格，起始金額為 0。\n接著依序輸入骰子點數，代表玩家往前移動的步數。\n每次移動後，落在的新格子會立即結算金錢變化。\n若該格需要失去金錢，但玩家的金額不足，則只會扣到 0 元，不會變成負數。\n棋盤是環形的，當超過第 N 格時，會回到第 1 格繼續往前走。\n注意：玩家剛開始站在第 1 格時，不會結算金額，只有移動後才會結算。\n請計算所有骰子點數執行完畢後，玩家的最終金額",examples:[{input:"5\n10 -5 0 20 -10\n3\n1 2 3",output:"15",explanation:"起始在第 1 格，金額 0\n走 1 → 到第 2 格（-5）：扣到 0 → 金額 0\n走 2 → 到第 4 格（+20）：金額 20\n走 3 → 從第 4 格往前 3 步 → 到第 2 格（-5）：20 → 15\n最終金額 = 15"},{input:"4\n50 -20 10 -5\n4\n4 1 1 1",output:"35",explanation:"起始在第 1 格，金額 0\n走 4 → 到第 1 格：+50 → 50\n走 1 → 到第 2 格：-20 → 30\n走 1 → 到第 3 格：+10 → 40\n走 1 → 到第 4 格：-5 → 35\n最終金額 = 35"}],testCases:[{input:"5\n10 -5 0 20 -10\n3\n1 2 3",expectedOutput:"15",score:10},{input:"4\n50 -20 10 -5\n4\n4 1 1 1",expectedOutput:"35",score:10},{input:"3\n-10 5 -5\n2\n1 2",expectedOutput:"0",score:10},{input:"2\n50 -30\n2\n6 6",expectedOutput:"100",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M2-06-SimContest/WP-04.sb3"},{id:"WP-05",code:"M2-06-WP-05",title:"傳球遊戲",description:"學校運動會舉辦了一個趣味傳球比賽，所有參賽同學圍成一個圓圈，互相傳球。\n每個同學有一個編號（從 1 到 N）。\n遊戲規則如下：\t比賽開始時，球在 1 號同學手上。\n傳球方式：每次傳球都固定「隔 K 個人」，把球傳給下一位同學。\n例如：K=1 代表傳給下一個人，K=2 代表跳過 1 人後傳給下一個人。\n傳球會一直持續，直到球再次回到 1 號同學手上，比賽才結束。\n請你模擬這個傳球遊戲，輸出整個過程中，球依序落在誰的手上（包含最初的 1 號）",examples:[{input:"5\n2",output:"1 3 5 2 4 1",explanation:"第一行輸入5，共有 5 個人，起始在 1。\n第二行輸入2，傳球每隔 2 人 → 傳到第 3 人。\n傳球過程：1 → 3 → 5 → 2 → 4 → 1\n程式輸出包含起點 → 1 3 5 2 4 1。"},{input:"6\n3",output:"1 4 1",explanation:"第一行輸入6，共有 6 個人，起始在 1。\n第二行輸入3，傳球每隔 3 人 → 傳到第 4 人。\n傳球過程：1 → 4 → 1\n程式輸出包含起點 → 1 4 1。"},{input:"4\n1",output:"1 2 3 4 1",explanation:"第一行輸入4，共有 4 個人，起始在 1。\n第二行輸入1，傳球每隔 1 人 → 傳到第 2 人。\n傳球過程：1 → 2 →3 → 4 → 1\n程式輸出包含起點 → 1 2 3 4 1。"},{input:"12\n9",output:"1 10 7 4 1",explanation:"第一行輸入12，共有 12 個人，起始在 1。\n第二行輸入9，傳球每隔 9 人 → 傳到第 10 人。\n傳球過程：1 → 10 → 7 → 4 → 1\n程式輸出包含起點 → 1 10 7 4 1。"}],testCases:[{input:"5\n2",expectedOutput:"1 3 5 2 4 1",score:10},{input:"4\n1",expectedOutput:"1 2 3 4 1",score:10},{input:"6\n3",expectedOutput:"1 4 1",score:10},{input:"12\n9",expectedOutput:"1 10 7 4 1",score:10}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M2-06-SimContest/WP-05.sb3"},{id:"cyjunior-001",code:"M2-06-cyjunior-001",title:"智慧手環的健康挑戰",description:"為了響應教育部推廣的「新世代健康校園」計畫，學校本學期發給每位同學一支「智慧運動手環」。這支手環不僅能顯示時間，還內建了高精度的三軸加速規，能夠以「小時」為單位，記錄使用者的步數活動量。\n主角小華為了爭取期末的「健康小鐵人」獎章，立志要嚴格執行運動計畫。根據手環的說明書，系統設定了一個「活躍門檻值 (K)」。如果某一小時內的步數低於這個門檻，該小時就會被系統判定為「靜態時段」，並記上一筆「久坐警告」。\n然而，為了避免學生長時間維持靜態，系統設計了一套嚴厲的連續懲罰機制：如果手環偵測到使用者連續兩個小時（含）以上都處於「靜態時段」，系統會判定這是極不健康的行為。因此，從連續違規的第二個小時開始，該次警告將會被加倍懲罰（也就是該小時會被記 2 次警告）。只有當某一小時的步數成功達到門檻時，這個連續違規的狀態才會解除，計數器才會重置。\n請你根據小華手環中匯出的 N 小時歷史數據，幫他計算這段時間內，系統累計發出了幾次警告訊號",examples:[{input:"5\n1000\n800 900 1200 500 400",output:"6",explanation:"800 (=1000): 達標，中斷連續狀態\n500 (<1000): 警告+1 (累計4)\n400 (<1000): 連續未達標，警告+2 (累計6)"},{input:"4\n500\n600 700 800 900",output:"0",explanation:"所有時段皆達標，無警告。"}],testCases:[{input:"3\n1000\n1200 1500 2000",expectedOutput:"0",score:10},{input:"4\n800\n500 600 700 400",expectedOutput:"7",score:15},{input:"5\n100\n50 150 50 50 150",expectedOutput:"4",score:20},{input:"6\n2000\n1000 1000 1000 2500 1000 1000",expectedOutput:"8",score:25},{input:"10\n500\n400 400 400 600 600 400 400 400 400 400",expectedOutput:"14",score:30}],difficulty:"L4",difficultyLabel:"L4｜精熟",sb3Path:"m0/M2-06-SimContest/cyjunior-001.sb3"},{id:"cyjunior-003",code:"M2-06-cyjunior-003",title:"資源回收車的極限挑戰",description:"每週的資源回收工作結束後，回收車準備將垃圾運走。但是，回收車的剩餘空間有限，只剩下 K 的容量單位。 待清運的回收物還有 N包，每包的大小不一。為了讓校園看起來最整潔，衛生組長希望盡可能載走「最多包」的回收物（數量越多越好，而不是體積最大）。 請你運用「貪婪法則」，幫忙計算在容量 K 的限制下，這台回收車最多能載走幾包回收物？ (提示：為了拿走最多包，我們應該優先選擇體積小的，還是體積大的呢？)",examples:[{input:"5\n10\n5 8 3 2 4",output:"3",explanation:"1. 排序(小到大)：2, 3, 4, 5, 8\n2. 裝入2 (剩8)\n3. 裝入3 (剩5)\n4. 裝入4 (剩1)\n5. 下一個是5，裝不下。共載走 3 包。"},{input:"4\n20\n10 10 10 10",output:"2",explanation:"10+10=20，剛好裝滿，共 2 包。"}],testCases:[{input:"3\n100\n20 30 40",expectedOutput:"3",score:10},{input:"5\n10\n20 30 40 50 60",expectedOutput:"0",score:15},{input:"5\n10\n1 2 3 4 5",expectedOutput:"4",score:20},{input:"6\n15\n5 10 5 10 5 10",expectedOutput:"3",score:25},{input:"8\n50\n100 2 100 3 100 5 100 8",expectedOutput:"4",score:30}],difficulty:"L4",difficultyLabel:"L4｜精熟",sb3Path:"m0/M2-06-SimContest/cyjunior-003.sb3"},{id:"TYTN-08",code:"M2-06-TYTN-08",title:"綠能任務挑戰",description:"為了推動淨零城市，玩家要在地圖中收集綠能點數（正值）並應對污染事件（負值）。\n地圖共有 N 個地點，每格可能代表「吸收碳」（正值）、「排放碳」（負值）或「無變化」（0）。\n玩家從第 1 格出發（初始能量為 0，不計入第 1 格的能量值）。每次依骰子的點數往前移動，並在抵達的新地點時計算能量變化。\n能量規則：\n1. 若總能量 > 50，觸發「能源過載」，能量強制維持在 50。\n2. 若總能量 ≤ 0，觸發「環境危機」，系統將能量自動補助為 5。\n3. 地圖為環狀，超過第 N 格後會回到第 1 格。\n請計算所有移動結束後的「最終能量值」，並輸出過程中曾達到的「最高能量值」",examples:[{input:"4\n25 10 30 -5\n4\n1 1 2 1",output:"50 50",explanation:"能量多次上升超過 50，觸發能源過載維持在 50。\n最終能量 50，最高能量也為 50。"},{input:"5\n10 -5 0 20 -10\n3\n1 2 3",output:"20 25",explanation:"玩家依序移動並累計能量，過程中最高能量達 25。\n最後能量為 20。"}],testCases:[{input:"4\n25 10 30 -5\n4\n1 1 2 1",expectedOutput:"50 50",score:10},{input:"5\n10 -5 0 20 -10\n3\n1 2 3",expectedOutput:"20 25",score:10},{input:"3\n5 -10 40\n3\n1 1 1",expectedOutput:"50 50",score:10},{input:"6\n0 0 -20 10 5 30\n4\n3 3 3 3",expectedOutput:"20 20",score:10},{input:"4\n50 -50 50 -50\n4\n1 1 1 1",expectedOutput:"50 50",score:10}],difficulty:"L4",difficultyLabel:"L4｜精熟",sb3Path:"m0/M2-06-SimContest/TYTN-08.sb3"}]}}}]);